function FastSearch(){
    $("#story").attr("autocomplete","off");

    $("#story").keyup(function(){
        var a = $(this).val();
        if (a.length === 0){
            $("#searchsuggestions").fadeOut();
        } else if (dle_search_value !== a && a.length >= dle_min_search) {
            clearInterval(dle_search_delay);
            dle_search_delay = setInterval(function(){
                dle_do_search(a)
            }, 600);
        }
    });
}

function dle_do_search(a){
    clearInterval(dle_search_delay);
    $("#searchsuggestions").remove();
    $("body").append("<div id='searchsuggestions' style='display:none'></div>");

    $.post(dle_root + "engine/ajax/controller.php?mod=search", {query: "" + a, user_hash: dle_login_hash}, function(b){
        $("#searchsuggestions").html(b).fadeIn().css({position: "absolute", top: 0, left: 0}).position({
            my: "left top",
            at: "left bottom",
            of: "#story",
            collision: "fit flip"
        });
    });
    dle_search_value = a;
}

$(document).on("click", function(e) {
    var container = $("#searchsuggestions");
    if (!container.is(e.target) && container.has(e.target).length === 0 && !$("#story").is(e.target)) {
        container.fadeOut();
    }
});

$("#searchsuggestions").on("click", function(e) {
    e.stopPropagation();
});
